types:
[Node: {} as {
        context: typeof context;
        events: TodoEvent;
      }]

ADD.actions:
[Node: assign({
            todoRefs: ({ context, event, spawn }) => ({
              ...context.todoRefs,
              [event.id]: spawn(todoMachine)
            })
          })]

SET_COMPLETE.actions:
[Node: sendTo(
            ({ context, event }) => {
              return context.todoRefs[event.id];
            },
            { type: 'SET_COMPLETE' }
          )]
